from calendar import monthrange
from datetime import date, datetime, timedelta
from typing import Iterator


_WEEKDAYS = {
    "MO": 0, "TU": 1, "WE": 2, "TH": 3,
    "FR": 4, "SA": 5, "SU": 6,
}


def _candidate_dates(
    rule: dict,
    start: datetime,
    lower: date,
    upper: date,
    interval: int,
) -> Iterator[date]:
    """Yield distinct pattern-matching dates in [lower, upper], ascending."""
    if lower > upper:
        return

    freq = rule["freq"]
    start_date = start.date()
    lo = lower.toordinal()
    hi = upper.toordinal()

    if freq == "daily":
        anchor = start_date.toordinal()
        first = max(0, (lo - anchor + interval - 1) // interval)
        last = (hi - anchor) // interval

        for k in range(first, last + 1):
            yield date.fromordinal(anchor + k * interval)
        return

    if freq == "weekly":
        # Monday of the week containing start.
        anchor = start_date.toordinal() - start.weekday()
        step = 7 * interval
        weekdays = sorted({
            _WEEKDAYS[name] for name in rule["by_weekday"]
        }) if "by_weekday" in rule else [start.weekday()]

        # The preceding active week might overlap the lower bound.
        first = max(0, (lo - anchor) // step)
        last = (hi - anchor) // step

        for k in range(first, last + 1):
            monday = anchor + k * step
            for weekday in weekdays:
                ordinal = monday + weekday
                if lo <= ordinal <= hi:
                    yield date.fromordinal(ordinal)
        return

    if freq == "monthly":
        anchor = start.year * 12 + start.month - 1
        lower_month = lower.year * 12 + lower.month - 1
        upper_month = upper.year * 12 + upper.month - 1
        first = max(0, (lower_month - anchor) // interval)
        last = (upper_month - anchor) // interval

        nth = rule.get("by_nth_weekday")
        month_days = rule.get("by_month_day", [start.day])

        for k in range(first, last + 1):
            year, month_zero = divmod(anchor + k * interval, 12)
            month = month_zero + 1
            first_weekday, days_in_month = monthrange(year, month)

            if nth is not None:
                n, weekday_name = nth
                weekday = _WEEKDAYS[weekday_name]

                if n > 0:
                    day = (
                        1
                        + (weekday - first_weekday) % 7
                        + 7 * (n - 1)
                    )
                else:
                    last_weekday = (
                        first_weekday + days_in_month - 1
                    ) % 7
                    day = (
                        days_in_month
                        - (last_weekday - weekday) % 7
                        - 7 * (-n - 1)
                    )

                days = [day] if 1 <= day <= days_in_month else []
            else:
                # Resolve negative days and deduplicate equivalent entries.
                resolved = {
                    d if d > 0 else days_in_month + d + 1
                    for d in month_days
                }
                days = sorted(
                    d for d in resolved if 1 <= d <= days_in_month
                )

            for day in days:
                candidate = date(year, month, day)
                if lower <= candidate <= upper:
                    yield candidate
        return

    if freq == "yearly":
        first = max(0, (lower.year - start.year) // interval)
        last = (upper.year - start.year) // interval

        for k in range(first, last + 1):
            year = start.year + k * interval
            if start.day > monthrange(year, start.month)[1]:
                continue

            candidate = date(year, start.month, start.day)
            if lower <= candidate <= upper:
                yield candidate


def expand(rule: dict, window_start: str, window_end: str) -> list[str]:
    """
    Expand a fixed-offset recurrence into UTC timestamps in
    [window_start, window_end).

    Without count, jump directly to the relevant recurrence periods.
    With count, replay from start so excluded occurrences still count.
    """
    freq = rule["freq"]
    interval = rule.get("interval", 1)

    # Validate before any early return, including for empty windows.
    if freq not in {"daily", "weekly", "monthly", "yearly"}:
        raise ValueError(f"Unknown frequency: {freq!r}")
    if interval < 1:
        raise ValueError("interval must be at least 1")
    if "count" in rule and "until" in rule:
        raise ValueError("count and until are mutually exclusive")
    if "by_month_day" in rule and "by_nth_weekday" in rule:
        raise ValueError(
            "by_month_day and by_nth_weekday are mutually exclusive"
        )

    # Use naive datetimes internally: UTC for input/output conversion,
    # local wall time for all recurrence calculations.
    start = datetime.fromisoformat(rule["start"])
    offset = timedelta(minutes=rule["utc_offset_minutes"])
    utc_start = datetime.fromisoformat(window_start[:-1])
    utc_end = datetime.fromisoformat(window_end[:-1])

    if utc_start >= utc_end:
        return []

    local_start = utc_start + offset
    local_end = utc_end + offset
    until = (
        datetime.fromisoformat(rule["until"])
        if "until" in rule
        else None
    )
    count = rule.get("count")

    if local_end <= start:
        return []
    if until is not None and (until < start or until < local_start):
        return []

    scan_start = start if count is not None else max(start, local_start)
    last_date = local_end.date()
    if until is not None:
        last_date = min(last_date, until.date())

    excluded = {
        datetime.fromisoformat(value)
        for value in rule.get("exclude", [])
    }
    time_of_day = start.time()
    occurrences_seen = 0
    result: list[str] = []

    for candidate_date in _candidate_dates(
        rule, start, scan_start.date(), last_date, interval
    ):
        occurrence = datetime.combine(candidate_date, time_of_day)

        if occurrence < scan_start:
            continue
        if occurrence >= local_end:
            break
        if until is not None and occurrence > until:
            break

        # Count valid recurrence occurrences before applying exclusions.
        occurrences_seen += 1

        if occurrence >= local_start and occurrence not in excluded:
            utc_occurrence = occurrence - offset
            result.append(utc_occurrence.strftime("%Y-%m-%dT%H:%MZ"))

        if count is not None and occurrences_seen >= count:
            break

    return result
